import json,os,time
from pathlib import Path
wanted={"Uid","Gid","Groups","CapInh","CapPrm","CapEff","CapBnd","CapAmb","NoNewPrivs","NSpid","Pid"}
s={k:v.strip() for line in Path("/proc/self/status").read_text().splitlines() for k,sep,v in [line.partition(":")] if k in wanted}
allowed={"PATH","LANG","LC_ALL","HOME","TZ","TERM","USER","LOGNAME","TMPDIR","PWD","SHLVL","_"}
print(json.dumps({"scope":"credential/environment/namespace metadata only","pid":os.getpid(),"pid_namespace":os.readlink("/proc/self/ns/pid"),"uid":os.getuid(),"euid":os.geteuid(),"gid":os.getgid(),"groups":os.getgroups(),"status":s,"uid_map":Path("/proc/self/uid_map").read_text(),"gid_map":Path("/proc/self/gid_map").read_text(),"setgroups":Path("/proc/self/setgroups").read_text(),"user_namespace":os.readlink("/proc/self/ns/user"),"overflowgid":Path("/proc/sys/kernel/overflowgid").read_text(),"environment_keys":sorted(os.environ),"selected_environment":{k:v for k,v in os.environ.items() if k in allowed}},sort_keys=True),flush=True)
time.sleep(20)
